<?php $page = $page ?? 'applicant-login'; $isHr = $page === 'hr'; $isSignup = $page === 'signup'; ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= $isHr ? 'HR Sign In' : ($isSignup ? 'Create Account' : 'Applicant Sign In') ?> | RJC Corporate Center</title><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><style>:root{--navy:#0b1f3a;--indigo:#4f46e5;--ink:#172033;--muted:#667085;--line:#dfe6f0}*{box-sizing:border-box}body{min-height:100vh;margin:0;background:#f5f7fb;color:var(--ink);font-family:Inter,Arial,sans-serif}.layout{min-height:100vh;display:grid;grid-template-columns:minmax(360px,.9fr) minmax(480px,1.1fr)}.side{position:relative;overflow:hidden;padding:56px clamp(34px,6vw,100px);color:#fff;background:linear-gradient(135deg,#071a31,#133e72 60%,#365eb8)}.side:before,.side:after{content:"";position:absolute;border-radius:50%;background:#fff;opacity:.06}.side:before{width:480px;height:480px;right:-210px;top:-150px}.side:after{width:380px;height:380px;left:-220px;bottom:-160px}.brand,.copy{position:relative;z-index:1}.brand{display:flex;align-items:center;gap:12px;font-weight:800}.mark{width:44px;height:44px;display:grid;place-items:center;border-radius:13px;background:#fff;color:var(--navy);font-size:12px;box-shadow:0 12px 30px #06152c55}.brand small{display:block;font-size:10px;font-weight:500;opacity:.72;letter-spacing:.04em;margin-top:3px}.copy{max-width:490px;margin-top:clamp(92px,18vh,185px)}.eyebrow{display:inline-flex;padding:7px 10px;border:1px solid #ffffff2e;background:#ffffff12;border-radius:99px;font-size:11px;font-weight:700;letter-spacing:.08em;text-transform:uppercase}.copy h1{font-size:clamp(34px,4.1vw,56px);line-height:1.05;letter-spacing:-.055em;margin:22px 0 18px}.copy p{font-size:15px;line-height:1.7;max-width:430px;color:#dce9ff}.benefits{display:grid;gap:14px;margin-top:38px;font-size:13px;color:#eaf1ff}.benefits div:before{content:"✓";display:inline-grid;place-items:center;width:23px;height:23px;margin-right:11px;border-radius:8px;background:#ffffff1a;color:#a9f8c7}.form-area{display:grid;place-items:center;padding:40px 28px;background:radial-gradient(circle at 100% 0,#e7edff 0,transparent 32%),#f8fafc}.card{width:min(430px,100%)}.back{display:inline-flex;color:var(--muted);font-size:12px;font-weight:600;text-decoration:none;margin-bottom:38px}.back:hover{color:var(--indigo)}h2{font-size:29px;letter-spacing:-.045em;margin:0 0 9px}.intro{margin:0 0 29px;color:var(--muted);font-size:13px;line-height:1.6}.grid{display:grid;grid-template-columns:1fr 1fr;gap:0 13px}.field{margin-top:17px}.full{grid-column:1/-1}.field label{display:block;font-size:12px;font-weight:700;margin-bottom:8px;color:#344054}input{width:100%;border:1px solid var(--line);border-radius:11px;background:#fff;padding:13px 14px;font:inherit;font-size:13px;outline:0;transition:.18s}input:focus{border-color:#7772ed;box-shadow:0 0 0 4px #4f46e51c}button{width:100%;border:0;border-radius:11px;margin-top:25px;padding:14px;background:linear-gradient(135deg,#4f46e5,#3730a3);color:#fff;font:700 13px Inter;box-shadow:0 12px 22px #4f46e538;cursor:pointer;transition:.18s}button:hover{transform:translateY(-1px);box-shadow:0 16px 28px #4f46e548}.message{min-height:20px;margin-top:14px;color:#c93636;font-size:12px;text-align:center}.link{margin:27px 0 0;text-align:center;color:#667085;font-size:12px}.link a{font-weight:700;color:var(--indigo);text-decoration:none}.help{margin:32px 0 0;text-align:center;color:#98a2b3;font-size:11px}@media(max-width:800px){.layout{grid-template-columns:1fr}.side{display:none}.form-area{min-height:100vh}.grid{grid-template-columns:1fr}.back{margin-bottom:30px}}</style></head><body><main class="layout"><section class="side"><div class="brand"><div class="mark">RJC</div><div>RJC Corporate Center<small>RECRUITMENT MANAGEMENT</small></div></div><div class="copy"><span class="eyebrow"><?= $isHr ? 'Secure HR workspace' : 'Applicant portal' ?></span><h1><?= $isHr ? 'Recruit with clarity and confidence.' : ($isSignup ? 'Your next role starts here.' : 'Start where you left off.') ?></h1><p><?= $isHr ? 'Manage security personnel recruitment from one focused workspace—from applications and document checks to screening outcomes.' : 'Keep your profile current, review open opportunities, and follow every stage of your application with confidence.' ?></p><div class="benefits"><div>Simple, guided application journey</div><div>Clear recruitment status tracking</div><div>Secure account access</div></div></div></section><section class="form-area"><div class="card"><a class="back" href="<?= $isHr ? 'applicant.php' : 'applicant.php' ?>">← <?= $isHr ? 'View applicant portal' : 'Browse open postings' ?></a><h2><?= $isHr ? 'Welcome back' : ($isSignup ? 'Create your account' : 'Welcome back') ?></h2><p class="intro"><?= $isHr ? 'Sign in to your RJC HR workspace to continue managing recruitment.' : ($isSignup ? 'Create your account first, then complete your profile when applying for a position.' : 'Sign in to complete your profile and track your application progress.') ?></p><?php if ($isSignup): ?><form id="signup"><div class="grid"><div class="field"><label>First name</label><input name="first_name" required autocomplete="given-name" placeholder="Juan"></div><div class="field"><label>Surname</label><input name="surname" required autocomplete="family-name" placeholder="Dela Cruz"></div><div class="field full"><label>Middle name <span style="font-weight:400;color:#98a2b3">(optional)</span></label><input name="middle_name" autocomplete="additional-name" placeholder="Santos"></div><div class="field"><label>Username</label><input name="username" required pattern="[A-Za-z0-9_.-]{3,50}" autocomplete="username" placeholder="juan.delacruz"></div><div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="you@email.com"></div><div class="field"><label>Password</label><input name="password" type="password" minlength="8" required autocomplete="new-password" placeholder="At least 8 characters"></div><div class="field"><label>Confirm password</label><input name="confirm_password" type="password" minlength="8" required autocomplete="new-password" placeholder="Repeat password"></div></div><button>Create applicant account →</button></form><div id="message" class="message" aria-live="polite"></div><div class="link">Already registered? <a href="applicant_login.php">Sign in instead</a></div><?php else: ?><form id="login"><div class="field"><label><?= $isHr ? 'Username' : 'Username or email' ?></label><input name="<?= $isHr ? 'username' : 'identity' ?>" required autocomplete="username" placeholder="<?= $isHr ? 'Enter your username' : 'name@example.com' ?>"></div><div class="field"><label>Password</label><input name="password" type="password" required autocomplete="current-password" placeholder="Enter your password"></div><button>Sign in to <?= $isHr ? 'HR workspace' : 'applicant portal' ?> →</button></form><div id="message" class="message" aria-live="polite"></div><?php if(!$isHr): ?><div class="link">New to RJC? <a href="applicant_signup.php">Create your applicant account</a></div><?php else: ?><p class="help">Authorized RJC Corporate Center personnel only</p><?php endif; ?><?php endif; ?></div></section></main><script><?php if($isSignup): ?>document.querySelector('#signup').addEventListener('submit',async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));if(data.password!==data.confirm_password){document.querySelector('#message').textContent='Passwords do not match.';return}const b=e.currentTarget.querySelector('button');b.disabled=true;try{const r=await fetch('api/applicant_signup.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}),d=await r.json();if(d.ok)location.href='applicant.php';else document.querySelector('#message').textContent=d.message||'Account could not be created.'}catch{document.querySelector('#message').textContent='The sign-up service is unavailable.'}finally{b.disabled=false}})<?php else: ?>const next=new URLSearchParams(location.search).get('next')||'applicant.php';document.querySelector('#login').addEventListener('submit',async e=>{e.preventDefault();const b=e.currentTarget.querySelector('button');b.disabled=true;try{const r=await fetch('api/<?= $isHr ? 'hr_login' : 'applicant_login' ?>.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))}),d=await r.json();if(d.ok)location.<?= $isHr ? 'replace' : 'href' ?>(<?= $isHr ? "'index.php'" : 'next' ?>);else document.querySelector('#message').textContent=d.message||'Sign-in failed.'}catch{document.querySelector('#message').textContent='The sign-in service is unavailable.'}finally{b.disabled=false}})<?php endif; ?></script></body></html>
